    insert into classroom_courses (slug, title, description, sort_order)
    insert into classroom_units (course_id, title, sort_order) values (v_course, 'Module 1 · Code', 1) returning id into v_unit;
    insert into classroom_lessons (unit_id, title, kind, sort_order, is_published) values (v_unit, 'Lesson 3 · The Red Cup', 'lesson', 2, false) returning id into v_plan;
    insert into classroom_lessons (unit_id, title, kind, sort_order, is_published) values (v_unit, 'Homework 3 · The Red Cup', 'homework', 12, false) returning id into v_hw;
  insert into classroom_blocks (lesson_id, type, payload, sort_order) values
  (v_plan, 'embed', $blk${"url": "https://classroom.wowteach.ru/lessons/reading10/u3.html"}$blk$::jsonb, 0),
  (v_plan, 'text', $blk${"html": "<div style=\"padding:16px 18px;background:#F2FAFE;border-radius:14px;border:2px solid #CFE6F4\"><h3 style=\"margin:0 0 6px;color:#0A5C86\">🔐 Как провести урок</h3><p style=\"margin:0 0 8px\">«Планы уроков» → этот урок → <b>«▶ Показ»</b>: урок откроется на весь экран. Демонстрируйте в Zoom <b>эту вкладку</b>. На экране ученика — только короткие инструкции по-английски: историю, задания и объяснения даёт учитель по этому плану.</p><p style=\"margin:0 0 8px\">Вверху справа выберите <b>30</b> или <b>40</b> минут — в режиме 40 появятся дополнительные экраны (розовые точки внизу). <b>⭐ Extra</b> — игры «If time», если осталось время: Code breaker, What's missing?, Find 5 words. Листать можно стрелками на клавиатуре.</p><p style=\"margin:0\">Ученику к уроку нужны <b>тетрадь и ручка</b> — напомните заранее. Звуки букв играют по нажатию; слова можно произносить самому.</p></div>"}$blk$::jsonb, 1),
  (v_plan, 'text', $blk${"html": "<h3>План урока · Lesson 3 · The Red Cup</h3><div style=\"background:#fff;border:1px solid #CFE6F4;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>Пройдено:</b> s a t p i n m d o g · I, the, a. &nbsp; <b>Новое:</b> c k e u r · said, are, you. &nbsp; <b>Длительность:</b> 30 мин (40 — с экранами «+»). &nbsp; <b>История:</b> Агент X прислал сообщение «Run! Get the red cup.» &nbsp; <b>К концу урока ученик:</b> называет звуки c k e u r, читает слова из пройденных букв, пишет их на слух, читает 4 строки истории. &nbsp; <b>Материалы:</b> тетрадь и ручка у ученика.</div><div style=\"background:#fff;border:1px solid #CFE6F4;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>Приёмы — одинаковые на всех уроках</b><p style=\"margin:6px 0\"><b>Слияние (blending).</b> Звуки не «рубим» по одному. Тянущиеся звуки (s, m, n, a, e…) тянем и сразу ведём к следующему: «ssa-a-a-t → sat». Короткие (c, k, t, p, d, g) не тянутся — соединяем с гласной: «ca… t → cat». Учитель показывает (I do) → вместе (We do) → ученик сам (You do).</p><p style=\"margin:6px 0\"><b>Ошибка.</b> Не называть слово за ученика. Показать на букву: <i>\"What sound?\"</i> → ученик называет → <i>\"Blend again.\"</i> → читает слово заново. Ошибся в звуке дважды — отметить для «Agent check» следующего урока.</p><p style=\"margin:6px 0\"><b>Звуки.</b> Звук, а не имя буквы: «к», а не «си». Без призвука «э» на конце (не «пэ», а «п»). u — ближе к русскому «а»; e — короткое «э» без «й»; r — язык не дрожит.</p><p style=\"margin:6px 0\"><b>Экран ученика</b> — только короткие инструкции по-английски. Историю, задания и объяснения даёт учитель.</p></div><table style=\"width:100%;border-collapse:collapse;font-size:14px\"><tr><th style=\"background:#0A5C86;color:#fff;padding:7px 8px;text-align:left\">Этап</th><th style=\"background:#0A5C86;color:#fff;padding:7px 8px;text-align:left\">Что делаем</th><th style=\"background:#0A5C86;color:#fff;padding:7px 8px;text-align:left\">Teacher's language</th><th style=\"background:#0A5C86;color:#fff;padding:7px 8px;text-align:left\">Student's language</th><th style=\"background:#0A5C86;color:#fff;padding:7px 8px;text-align:left\">Примечания</th></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>1 · Mission</b><br><span style=\"color:#6F6A8A\">1 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Мотивация: пришло сообщение, часть значков ещё не знаем.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"New message from Agent X! Look — some code is new.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"We can't read it!\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Старые буквы уже вписаны, новые — серые. Сообщение прочитаем в конце урока.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>2 · Agent check</b><br><span style=\"color:#6F6A8A\">1,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Минутная проверка: ученик называет звуки всех значков в ключе.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Say the sounds! Go!\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">/s/, /æ/, /t/, /p/…</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Нажатие — зелёная рамка и звук. Ошибся — нажмите ещё раз: рамка станет красной. Красные — повторить в уроке и отметить для себя.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>3 · Tricky words</b><br><span style=\"color:#6F6A8A\">0,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Повтор слов-исключений прошлых уроков.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Read the tricky words.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"I · the · a\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Читаются целиком, по звукам не разбираем.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>4 · Chant</b><br><span style=\"color:#6F6A8A\">0,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Скороговорка урока 2, строки 3–4.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Read slowly… now fast!\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"A dog, a pot, a map, a pan — Dig it, Sam! Dig it, Dan!\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Кнопки 🐢 / ⚡ подсвечивают слова в ритме.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>+ Speed run</b><br><span style=\"color:#6F6A8A\">+3 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Беглость: 18 слов на время.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Read fast! Go!\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">sat, pin, dog, map…</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Рекорд сохраняется. Сравниваем только с собой.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>5 · HW check</b><br><span style=\"color:#6F6A8A\">1 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Ошибки ДЗ.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Read this word. Sound by sound.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"p-e-n — pen.\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1–2 слова из «Журнала ДЗ».</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>6–10 · New code ×5</b><br><span style=\"color:#6F6A8A\">3 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Новые звуки c, k, e, u, r — экран на букву.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Tap to unlock! This is c. Sound /k/. Cat. Say /k/.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"/k/ /k/ /k/ — cat.\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">c и k — одна буква-звук /k/ (скажите по-русски). e — короткое «э» без «й»; u — ближе к «а»; r — язык не дрожит. Значок попадает в ключ внизу.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>11 · Hear it</b><br><span style=\"color:#6F6A8A\">1,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Фонематический слух: есть ли звук /e/.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Listen. Do you hear /e/?\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"Yes!\" / \"No!\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">pen, pin, ten, tan, net, nut. Затем устно разделить: c-a-t, r-e-d.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>12 · Write it</b><br><span style=\"color:#6F6A8A\">1,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Письмо новых букв по прописям.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Look. Start at 1. Follow the arrows. Write c — three times.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">(пишет, говорит звук)</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Ученик пишет и одновременно произносит звук — так буква запоминается быстрее.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>13 · Copy</b><br><span style=\"color:#6F6A8A\">1 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Списать слова.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Copy: cat, red. Show me!\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">(показывает тетрадь)</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">—</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>+ Copy more</b><br><span style=\"color:#6F6A8A\">+2 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Списать ещё 3 слова.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Copy and check.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">sun, kid, pen</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"></td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>14 · Blending</b><br><span style=\"color:#6F6A8A\">3 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Слияние звуков в слово.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Tap the letters. Say the sounds. Blend. Read!\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"c-a… cat!\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Приём «слияние» — см. «Приёмы» выше. После последнего слова — «✔ Done →».</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>15 · Word chain</b><br><span style=\"color:#6F6A8A\">1,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Цепочка: меняется одна буква.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"One letter is new. Read!\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">rat → cat → cut → cup → pup → pop → pot → pet → pen → ten</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Новая буква — розовая. Самый сильный приём на внимание к каждой букве.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>+ Real or fake?</b><br><span style=\"color:#6F6A8A\">+3 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Чтение без угадывания.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Read it. Real or fake?\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"Dut — fake!\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Выдуманные слова тоже читаются вслух.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>16 · Word building</b><br><span style=\"color:#6F6A8A\">1,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Собрать слово из букв-магнитов.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Make the word.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">c-a-t</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Ошибся — нажать на последнюю букву в слове.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>17 · Tricky words</b><br><span style=\"color:#6F6A8A\">1 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Новые слова-исключения.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"These words are tricky. Remember them!\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"said · are · you\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">По-русски: «читаются не по правилам, запоминаем целиком».</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>18 · Read</b><br><span style=\"color:#6F6A8A\">0,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Слова-исключения во фразе.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Read.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"You are a cat!\" said Sam.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"></td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>19 · Dictation</b><br><span style=\"color:#6F6A8A\">3 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Письмо на слух.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Listen and write.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">pen · cup · rat · kit</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Приём «звуки на пальцах»: ученик говорит слово, отгибает палец на каждый звук, пишет по звуку. Check — сверка.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>+ Dictation</b><br><span style=\"color:#6F6A8A\">+2 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Фраза на слух.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Listen and write.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">a red cup</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"></td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>20 · Phrases</b><br><span style=\"color:#6F6A8A\">0,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Чтение фраз.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Read.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">a red cup · a pet rat · Sam and Dan</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"></td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>21 · Decode</b><br><span style=\"color:#6F6A8A\">1 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Расшифровка: старые буквы вписаны, новые открывает ученик.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Tap the new code. Read the message!\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"Run! Get the red cup.\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Слова-исключения стоят в сообщении целиком.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>22 · Story</b><br><span style=\"color:#6F6A8A\">1,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Чтение текста.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Read the story.\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">(читает 4 строки)</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Перед чтением по-русски: ребята расшифровали сообщение и бегут в столовую.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>23 · True or false?</b><br><span style=\"color:#6F6A8A\">0,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Понимание.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"True or false?\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"True!\" / \"False!\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"></td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>24 · Chant</b><br><span style=\"color:#6F6A8A\">0,5 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Скороговорка урока 3, строки 1–2.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Read slowly… now fast!\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"Run, run, run in the sun! Get a cup, get a nut!\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Строки 3–4 — в начале урока 4.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>25 · Now I can</b><br><span style=\"color:#6F6A8A\">1 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Итог (I CAN).</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"What can you do now?\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"I can read c, k, e, u, r!\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Ученик отмечает галочки; счётчик слов. По-русски: что получилось сегодня.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>26 · Assign HW</b><br><span style=\"color:#6F6A8A\">1 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Выдать ДЗ.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Your homework: read aloud!\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">—</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">«Материалы» → «Задать ДЗ» → «Homework 3 · The Red Cup». Скажите: в ДЗ много чтения вслух.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>27 · Finishing</b><br><span style=\"color:#6F6A8A\">2 мин</span></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Обратная связь в обе стороны, оценка урока.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><i>\"Well done, agent! How was the mission?\"</i></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">\"Easy!\" / \"OK\" / \"Hard\"</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Монетки — за что. Что получилось хорошо + над чем поработать. Что было лёгким и трудным. Звёзды. Зацепка: «Куда ведёт карта? — Mission 4».</td></tr></table><p style=\"margin-top:10px\"><b>If time (⭐ Extra):</b> Code breaker — слово символами, ввести на время · What's missing? — c_t, s_n, r_d, p_n, k_d · Find 5 words — сетка букв.</p>"}$blk$::jsonb, 2),
  (v_plan, 'text', $blk${"html": "<h3>Домашнее задание</h3><p>Материал <b>«Homework 3 · The Red Cup»</b> в этом же юните: новые буквы, звук → буква, <b>слова вслух</b>, слово ↔ картинка, сортировка /e/ и /u/, собери слово, впиши букву, <b>фразы вслух</b>, история «верно / неверно», <b>история вслух</b>, скороговорка вслух. В ДЗ много чтения вслух. «Материалы» → «Задать ДЗ» → ученик → отметить.</p>"}$blk$::jsonb, 3)
  insert into classroom_blocks (lesson_id, type, payload, sort_order) values
  (v_hw, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/reading10/u3/sam_phone.webp\" alt=\"\" style=\"height:auto;max-width:160px;float:right;margin:0 0 8px 12px\"><b>Агент, ключ пополнился!</b></p><p>Сегодня ты открыл пять новых символов: <b>c k e u r</b>. Потренируйся, пока не пришло новое сообщение от Агента X.</p>"}$blk$::jsonb, 0),
  (v_hw, 'flashcards', $blk${"title": "Новые буквы. Нажми на карточку — услышишь звук буквы.", "cards": [{"text": "c", "image": "https://classroom.wowteach.ru/media/reading10/cipher/c.webp", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/c.mp3", "translation": "кошка (cat) · звук /k/"}, {"text": "k", "image": "https://classroom.wowteach.ru/media/reading10/cipher/k.webp", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/k.mp3", "translation": "ключ (key) · звук /k/"}, {"text": "e", "image": "https://classroom.wowteach.ru/media/reading10/cipher/e.webp", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/e.mp3", "translation": "яйцо (egg) · звук /e/"}, {"text": "u", "image": "https://classroom.wowteach.ru/media/reading10/cipher/u.webp", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/u.mp3", "translation": "зонт (umbrella) · звук /ʌ/"}, {"text": "r", "image": "https://classroom.wowteach.ru/media/reading10/cipher/r.webp", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/r.mp3", "translation": "ракета (rocket) · звук /r/"}]}$blk$::jsonb, 1),
  (v_hw, 'quiz', $blk${"title": "Послушай звук и выбери букву.", "questions": [{"q": "", "type": "single", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/e.mp3", "correct": [0], "options": [{"text": "e"}, {"text": "a"}, {"text": "i"}]}, {"q": "", "type": "single", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/u.mp3", "correct": [1], "options": [{"text": "o"}, {"text": "u"}, {"text": "a"}]}, {"q": "", "type": "single", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/r.mp3", "correct": [2], "options": [{"text": "n"}, {"text": "m"}, {"text": "r"}]}, {"q": "", "type": "single", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/c.mp3", "correct": [0], "options": [{"text": "c"}, {"text": "d"}, {"text": "g"}]}, {"q": "", "type": "single", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/k.mp3", "correct": [1], "options": [{"text": "t"}, {"text": "k"}, {"text": "p"}]}]}$blk$::jsonb, 2),
  (v_hw, 'speaking', $blk${"title": "Прочитай слова вслух и запиши себя 🎤", "html": "<p style=\"font-size:1.5em;line-height:1.7;word-spacing:.4em\">cat · kid · pen · sun · red · cup · rat · net · dog · map · sit · tap</p>", "sample": "", "sample_tts": {"text": "cat, kid, pen, sun, red, cup, rat, net, dog, map, sit, tap.", "voice": "en_GB-alba"}, "needs_review": true}$blk$::jsonb, 3),
  (v_hw, 'match', $blk${"title": "Прочитай слово и найди его картинку.", "pairs": [{"left": "cat", "right": "картинка cat", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/cat.webp"}, {"left": "sun", "right": "картинка sun", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/sun.webp"}, {"left": "pen", "right": "картинка pen", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/pen.webp"}, {"left": "cup", "right": "картинка cup", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/cup.webp"}, {"left": "red", "right": "картинка red", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/red_paint.webp"}, {"left": "kid", "right": "картинка kid", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/kid.webp"}]}$blk$::jsonb, 4),
  (v_hw, 'sort', $blk${"title": "Прочитай слова и распредели их: в каком слове звук /e/, а в каком — звук /u/?", "groups": [{"name": "e", "items": [{"text": "pen"}, {"text": "ten"}, {"text": "red"}, {"text": "net"}]}, {"name": "u", "items": [{"text": "sun"}, {"text": "cup"}, {"text": "run"}, {"text": "mug"}]}]}$blk$::jsonb, 5),
  (v_hw, 'order', $blk${"title": "Посмотри на картинку и собери слово из букв.", "items": [{"words": ["c", "a", "t"], "sentence": "cat", "image": "https://classroom.wowteach.ru/media/reading10/u3/cat.webp"}, {"words": ["s", "u", "n"], "sentence": "sun", "image": "https://classroom.wowteach.ru/media/reading10/u3/sun.webp"}, {"words": ["r", "e", "d"], "sentence": "red", "image": "https://classroom.wowteach.ru/media/reading10/u3/red_paint.webp"}, {"words": ["k", "i", "d"], "sentence": "kid", "image": "https://classroom.wowteach.ru/media/reading10/u3/kid.webp"}]}$blk$::jsonb, 6),
  (v_hw, 'gaps', $blk${"title": "Послушай слово и впиши пропущенную букву.", "mode": "type", "text": "p__e__n\nc__u__p\nr__e__d\ns__u__n\nk__i__t", "line_audio": ["", "", "", "", ""], "line_audio_tts": [{"text": "pen.", "voice": "en_GB-alba"}, {"text": "cup.", "voice": "en_GB-alba"}, {"text": "red.", "voice": "en_GB-alba"}, {"text": "sun.", "voice": "en_GB-alba"}, {"text": "kit.", "voice": "en_GB-alba"}], "line_image": ["https://classroom.wowteach.ru/media/reading10/u3/pen.webp", "https://classroom.wowteach.ru/media/reading10/u3/cup.webp", "https://classroom.wowteach.ru/media/reading10/u3/red_paint.webp", "https://classroom.wowteach.ru/media/reading10/u3/sun.webp", "https://classroom.wowteach.ru/media/reading10/u3/kit.webp"]}$blk$::jsonb, 7),
  (v_hw, 'speaking', $blk${"title": "Прочитай фразы вслух и запиши себя 🎤", "html": "<p style=\"font-size:1.4em;line-height:1.8\">a red cup<br>a pet rat<br>Sam and Dan<br>Get the pen!<br>Run, Dan, run!</p>", "sample": "", "sample_tts": {"text": "a red cup. a pet rat. Sam and Dan. Get the pen!. Run, Dan, run!", "voice": "en_GB-alba"}, "needs_review": true}$blk$::jsonb, 8),
  (v_hw, 'quiz', $blk${"title": "Прочитай историю и ответь: верно или неверно?", "material": "<p><img src=\"https://classroom.wowteach.ru/media/reading10/u3/scene_cup.webp\" alt=\"\" style=\"height:auto;max-width:100%;border-radius:12px\"></p><p style=\"font-size:1.25em;line-height:1.6\">“Run! Get the red cup!” said Sam.<br>The red cup sits on a mat.<br>Dan gets it. In the cup — a map!<br>Sam and Dan run.</p>", "questions": [{"q": "The cup is red.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "The cup sits on a pen.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "In the cup — a map.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}]}]}$blk$::jsonb, 9),
  (v_hw, 'speaking', $blk${"title": "Прочитай историю вслух и запиши себя 🎤", "html": "<p><img src=\"https://classroom.wowteach.ru/media/reading10/u3/scene_cup.webp\" alt=\"\" style=\"height:auto;max-width:100%;border-radius:12px\"></p><p style=\"font-size:1.25em;line-height:1.6\">“Run! Get the red cup!” said Sam.<br>The red cup sits on a mat.<br>Dan gets it. In the cup — a map!<br>Sam and Dan run.</p>", "sample": "", "sample_tts": {"text": "\"Run! Get the red cup!\" said Sam. The red cup sits on a mat. Dan gets it. In the cup — a map! Sam and Dan run.", "voice": "en_GB-alba"}, "needs_review": true}$blk$::jsonb, 10),
  (v_hw, 'speaking', $blk${"title": "Прочитай вслух скороговорку и запиши себя 🎤", "html": "<p style=\"font-size:1.3em;line-height:1.6\">Run, run, run in the sun!<br>Get a cup, get a nut!<br>A red cat, a red pen,<br>Ten red cups — run, run, run!</p>", "sample": "", "sample_tts": {"text": "Run, run, run in the sun! Get a cup, get a nut! A red cat, a red pen, Ten red cups — run, run, run!", "voice": "en_GB-alba"}, "needs_review": true}$blk$::jsonb, 11),
  (v_hw, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/reading10/u3/dan_wave.webp\" alt=\"\" style=\"height:auto;max-width:140px;float:right;margin:0 0 8px 12px\"><b>Миссия выполнена!</b></p><p>Новое сообщение Агента X придёт на следующем уроке. До встречи, агент!</p>"}$blk$::jsonb, 12)
